#include <bitset>
#include <iostream>

int main() {
    std::bitset<4> a(std::string("1010"));
    std::bitset<4> b(std::string("0110"));

    // Chained operation: a = a AND b OR b
    // a &= b results in 0010
    // | = b results in 0110 (final value)
    (a &= b) |= b;

    std::cout << "Result a: " << a << "\n"; // Output: 0110

    std::bitset<4> c(std::string("1111"));
    // c ^= b results in 1001
    c ^= b;
    std::cout << "Result c: " << c << "\n"; // Output: 1001
}
